} else {
  fs.writeFileSync(plik_zadania + '.tmp', JSON.stringify(nowe, null, 2));
  fs.renameSync(plik_zadania + '.tmp', plik_zadania);
  zapiszZdarzenie('m365_blad', { klient: z.klient, ip: z.ip, plik: z.nazwa_pdf, proby, krok, blad });
